package project.init.account.controller;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.PostMapping;import org.springframework.web.bind.annotation.RequestBody;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RestController;import project.init.account.domain.LogonResp;import project.init.account.domain.req.ChangePasswordReq;import project.init.account.domain.req.LoginReq;import project.init.account.domain.req.RegisterReq;import project.init.account.domain.req.ResetPassReq;import project.init.account.service.AuthService;import project.init.framework.authen.BearerContextHolder;import project.init.framework.error.BaseResponse;@Slf4j@RestController@RequestMapping("/auth")@RequiredArgsConstructorpublic class AuthController {    private final AuthService authService;    @PostMapping(value = "/login")    public ResponseEntity<LogonResp> login(@RequestBody LoginReq req) {        log.info("[login] accountCode={}", req.getAccountCode());        LogonResp resp = authService.login(req);        return ResponseEntity.ok(resp);    }    @PostMapping("/register")    public ResponseEntity<BaseResponse> register(@Valid @RequestBody RegisterReq req) {        log.info("[register] {}", req);        BaseResponse resp = authService.register(req);        return ResponseEntity.ok(resp);    }    @PostMapping("/reset-password")    public ResponseEntity<BaseResponse> resetPassword(@RequestBody ResetPassReq req) {        log.info("[resetPassword] {}", req);        BaseResponse resp = authService.resetPassword(req);        return ResponseEntity.ok(resp);    }    @PostMapping("/change-password")    public ResponseEntity<BaseResponse> changePassword(@RequestBody ChangePasswordReq req) {        String accountCode = BearerContextHolder.get().getAccountCode();        log.info("[changePassword] accountCode={}", accountCode);        BaseResponse resp = authService.changePassword(req, accountCode);        return ResponseEntity.ok(resp);    }}